let partner=read('partner',null), requests=read('requests',[]), accepted=read('accepted',[]), chats=read('chats',[]), currentPage='home', jobTab='all', demoLedger=read('demoLedger',[]), rides=read('rides',[]), activeRideId=read('activeRideId',''), rideView='customer', rideDraft={vehicle:'motorcycle',pickup:'Jaro · demo area',destination:'City Proper · demo area',pickupPoint:{x:85,y:65},dropPoint:{x:210,y:180},pinTarget:'pickup',schedule:'now'};
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>t.classList.remove('show'),2600)}
function navigate(page){currentPage=page;$$('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+page));$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$$('[data-page-link]').forEach(a=>a.classList.toggle('active',a.dataset.pageLink===page));window.scrollTo({top:0,behavior:'smooth'});if(page==='requests')renderRequests();if(page==='earn'){renderPartner();renderJobs()}if(page==='inbox')renderChat();if(page==='account')renderAccount();if(page==='admin')renderAdmin();if(page==='payments')renderPayments();if(page==='rides')renderRide()}
function openModal(html){$('#modalContent').innerHTML=html;$('#modalBackdrop').classList.add('open');document.body.style.overflow='hidden'}function closeModal(){$('#modalBackdrop').classList.remove('open');document.body.style.overflow=''}
function categoryByName(name){return CATEGORIES.find(c=>c.name===name)||CATEGORIES[0]}
function renderCategories(query=''){const q=query.toLowerCase().trim();const arr=CATEGORIES.filter(c=>!q||c.name.toLowerCase().includes(q)||c.items.some(s=>s.toLowerCase().includes(q)));$('#categoryGrid').innerHTML=arr.map(c=>`<button class="category-card" data-category="${c.name}"><span class="category-icon">${c.icon}</span><strong>${c.name}</strong><small>${c.items.length} services · ${c.mode==='both'?'local & online':c.mode}</small></button>`).join('')||'<div class="empty-state">No exact match. Try a service name—or choose “Other / Custom Request.”</div>';$$('[data-category]').forEach(b=>b.onclick=()=>openBooking(b.dataset.category))}
function subcategoryOptions(category,selected=''){return categoryByName(category).items.map(s=>`<option value="${esc(s)}" ${selected===s?'selected':''}>${esc(s)}</option>`).join('')}
function openBooking(category=''){
 const tomorrow=new Date(Date.now()+86400000).toISOString().slice(0,10),initial=category||'';
 openModal(`<h2 id="modalTitle">Make a service offer</h2><p class="modal-sub">Choose a service, explain the work, and offer the amount you’re willing to pay. A Partner can match it or suggest a different price.</p><form id="bookingForm"><div class="form-grid"><div class="field full"><label for="bookCategory">Service category</label><select id="bookCategory" required><option value="" ${!initial?'selected':''} disabled>Choose a service group</option>${CATEGORIES.map(c=>`<option value="${c.name}" ${c.name===initial?'selected':''}>${c.name} · ${c.items.length} options</option>`).join('')}</select></div><div class="field full"><label for="bookSubcategory">What specifically do you need?</label><select id="bookSubcategory" required><option value="">Choose a service</option>${initial?subcategoryOptions(initial):''}</select></div><div class="field full ${initial==='Other / Custom Request'?'':'hide'}" id="customServiceWrap"><label for="bookCustom">Describe the service you don’t see listed</label><input id="bookCustom" placeholder="What would you like help with?"></div><div class="field full"><label for="bookDetails">A few details</label><textarea id="bookDetails" required placeholder="What should the Partner know? Add size, quantity, or helpful notes."></textarea></div><div class="field"><label for="bookLocation">Location / area</label><input id="bookLocation" value="Iloilo City" required placeholder="e.g. Jaro, Iloilo"></div><div class="field"><label for="bookBudget">Your offer for the service (₱)</label><input id="bookBudget" type="number" min="50" step="50" placeholder="e.g. 500" required><small class="small-muted">This is your proposed service price. Partners can match it or counteroffer. No payment is charged in this demo.</small></div><div class="field"><label for="bookDate">Preferred date</label><input id="bookDate" type="date" min="${tomorrow}" value="${tomorrow}" required></div><div class="field"><label for="bookTime">Preferred time</label><select id="bookTime"><option>Flexible</option><option>Morning · 8 AM–12 PM</option><option>Afternoon · 12–5 PM</option><option>Evening · after 5 PM</option></select></div><div class="field full"><label>How can the work happen?</label><div class="radio-row"><label class="radio-pill selected"><input type="radio" name="mode" value="Nearby / in person" checked hidden>📍 Nearby / in person</label><label class="radio-pill"><input type="radio" name="mode" value="Online / remote" hidden>💻 Online / remote</label></div></div></div><div class="modal-actions"><button class="btn btn-outline" type="button" id="cancelBooking">Cancel</button><button class="btn btn-green" type="submit">Post offer for matching <span>→</span></button></div></form>`);
 const cat=$('#bookCategory'),sub=$('#bookSubcategory'),customWrap=$('#customServiceWrap'),custom=$('#bookCustom');
 function updateSub(){const name=cat.value;sub.innerHTML='<option value="">Choose a service</option>'+(name?subcategoryOptions(name):'');const other=name==='Other / Custom Request';customWrap.classList.toggle('hide',!other);custom.required=other}
 cat.onchange=updateSub;custom.required=initial==='Other / Custom Request';$('#cancelBooking').onclick=closeModal;
 $$('.radio-pill').forEach(x=>x.onclick=()=>{$$('.radio-pill').forEach(y=>y.classList.remove('selected'));x.classList.add('selected');x.querySelector('input').checked=true});
 $('#bookingForm').onsubmit=e=>{e.preventDefault();const chosen=cat.value,req={id:'r'+Date.now(),category:chosen,subcategory:sub.value,customService:chosen==='Other / Custom Request'?custom.value.trim():'',details:$('#bookDetails').value.trim(),location:$('#bookLocation').value.trim(),budget:Number($('#bookBudget').value),date:$('#bookDate').value,time:$('#bookTime').value,mode:$('input[name="mode"]:checked').value,status:'Waiting for Partner offers',offers:[],created:Date.now()};requests.unshift(req);save('requests',requests);closeModal();navigate('requests');toast('Offer posted. Partners can match your price or counteroffer.')}
}
function renderRequests(){
 const el=$('#requestsList');$('#emptyRequests').classList.toggle('hide',requests.length>0);if(!requests.length){el.innerHTML='';return}
 el.innerHTML=requests.map(r=>{const offers=r.offers||[],price=r.provider?(r.agreedPrice??r.budget):r.budget;const offerHtml=offers.map(o=>`<div class="offer-item"><div class="offer-top"><strong>${esc(o.partnerName)}</strong><span class="job-price">₱${Number(o.amount).toLocaleString()}</span></div><p>${o.kind==='match'?'Matched your offer':'Suggested a different price'}${r.provider&&r.provider===o.partnerName?' · selected':''}</p>${!r.provider?`<button class="btn btn-green btn-small" data-accept-offer="${esc(r.id)}" data-offer-id="${esc(o.id)}">Accept this offer →</button>`:''}</div>`).join('');
 const waiting=!r.provider&&!offers.length?'<div class="offer-note">No match yet. Your offer stays open—Partners can match it or send a different price.</div>':'';
 const matched=r.provider?`<div class="feature-bottom"><span class="small-muted">Partner chosen: <strong>${esc(r.provider)}</strong> · Agreed service price ₱${Number(price).toLocaleString()}</span><button class="btn btn-soft btn-small" data-chat-request="${esc(r.id)}">Message Partner ↗</button></div>`:'';
 return `<article class="request-card"><div class="job-top"><div><div class="job-title">${esc(r.category)}${r.subcategory?` · ${esc(r.subcategory)}`:''}${r.customService?` — ${esc(r.customService)}`:''}</div><p class="job-desc">${esc(r.details)}</p></div><span class="request-status ${r.provider?'matched':''}">${esc(r.status)}</span></div><div class="job-meta"><span>📍 ${esc(r.location)}</span><span>🗓 ${esc(r.date)} · ${esc(r.time)}</span><span>💰 ${r.provider?'Agreed price':'Your service offer'} ₱${Number(price).toLocaleString()}</span></div><div class="timeline"><i></i><span>Request posted</span><span class="line"></span><i style="background:${offers.length||r.provider?'#79aa8f':'#dce2da'}"></i><span>${r.provider?'Partner chosen':offers.length?`${offers.length} offer${offers.length===1?'':'s'} received`:'Waiting for offers'}</span></div>${offerHtml}${waiting}${matched}</article>`}).join('');
 $$('[data-accept-offer]').forEach(b=>b.onclick=()=>acceptRequestOffer(b.dataset.acceptOffer,b.dataset.offerId));$$('[data-chat-request]').forEach(b=>b.onclick=()=>navigate('inbox'))
}
function partnerModal(){
 const prior=partner||{},groups=CATEGORIES.map((c,i)=>`<details class="skill-group" ${i===0?'open':''}><summary><span>${c.icon} ${c.name}</span><small>${c.items.length} skills</small></summary><div class="skill-options">${c.items.map(s=>`<label class="check-option"><input type="checkbox" value="${esc(s)}" ${(prior.skills||[]).includes(s)?'checked':''}>${esc(s)}</label>`).join('')}</div></details>`).join('');
 openModal(`<h2 id="modalTitle">${partner?'Your Partner profile':'Become a PAHIMO Partner'}</h2><p class="modal-sub">Choose services you can do, set a starting amount, and make a separate offer for each customer request. Ikaw ang bahala sa imong presyo.</p><form id="partnerForm"><div class="form-grid"><div class="field"><label for="partnerName">Display name</label><input id="partnerName" required value="${esc(prior.name||'')}" placeholder="e.g. Jamie R."></div><div class="field"><label for="partnerArea">Service area</label><input id="partnerArea" required value="${esc(prior.area||'Iloilo City')}" placeholder="Your city or barangay"></div><div class="field"><label for="partnerRate">Typical starting amount (₱)</label><input id="partnerRate" required type="number" min="50" step="50" value="${prior.rate||250}" placeholder="e.g. 250"><small class="small-muted">Profile reference only. You set the exact offer per job.</small></div><div class="field"><label for="partnerAvailability">Availability</label><select id="partnerAvailability"><option ${prior.availability==='Flexible'?'selected':''}>Flexible</option><option ${prior.availability==='Weekdays'?'selected':''}>Weekdays</option><option ${prior.availability==='Weekends'?'selected':''}>Weekends</option><option ${prior.availability==='Evenings'?'selected':''}>Evenings</option></select></div><div class="field full"><label>What services can you offer? (choose at least one)</label><div class="skill-groups">${groups}</div></div><div class="field full"><details class="pricing-guide"><summary>Not sure what to charge? Open the optional price guide</summary><div class="pricing-guide-body"><p><strong>Guide only—not a fixed rate.</strong> You choose whether to match the customer’s offer or send your own quote.</p><div class="price-formula">Estimate = your labor/time + travel + materials or purchases + agreed extras</div><ul><li><strong>Delivery and errands:</strong> quote the service/trip fee; list distance, waiting, parking, and item costs separately.</li><li><strong>Home, cleaning, vehicle, and repairs:</strong> separate labor from parts/materials; confirm extra work before starting.</li><li><strong>Tutoring, beauty, and personal services:</strong> price per session or hour; clarify travel or product costs.</li><li><strong>Web, creative, business, and tech work:</strong> define the deliverables, project milestones, and included revisions.</li><li><strong>Events and other services:</strong> price the scope, quantity, time, people, and supplies; write down what is included.</li></ul><p>Check recent local prices and your real costs. PAHIMO does not have enough completed-job data to claim a local market rate yet; future guide ranges should be based on completed bookings and remain optional.</p></div></details></div><div class="field full"><label for="partnerBio">Short intro</label><textarea id="partnerBio" placeholder="Tell people what you’re good at, in your own words.">${esc(prior.bio||'')}</textarea></div></div><div class="verify-note"><span>🛡️</span><span>Clear scope and price before work begins. Build trust with completed jobs and reviews. Demo profiles are examples only.</span></div><details class="pricing-guide starter-policy"><summary>No ID yet? Read the proposed Starter Partner rules</summary><div class="pricing-guide-body"><p><strong>Inclusive path · draft only.</strong> A future Starter Partner could begin with one service, online-paid bookings only, and a lower job-value limit. Some sensitive services may need additional checks.</p><p>Online payouts require an approved, confirmed payout method. If you don’t have a bank or e-wallet, contact PAHIMO through a secure support setup—not ordinary chat. Don’t send wallet details here. Third-party payouts need a provider-approved process and explicit consent.</p><p><strong>Proposed fee waivers:</strong> no PAHIMO fee on cash jobs; no PAHIMO fee for Pabili/Pabakal under ₱100 within the same barangay. Your agreed service/labor and transport price is separate. For other work, any fee should be disclosed, based on your service charge (not reimbursed purchases), and capped. Rate/cap, verification, support, and payouts are not active in this demo.</p></div></details><div class="modal-actions"><button class="btn btn-outline" type="button" id="cancelPartner">Cancel</button><button class="btn btn-green" type="submit">${partner?'Save profile':'Create my Partner profile'} →</button></div></form>`);
 $('#cancelPartner').onclick=closeModal;$('#partnerForm').onsubmit=e=>{e.preventDefault();const skills=$$('#partnerForm input[type=checkbox]:checked').map(x=>x.value);if(!skills.length){toast('Choose at least one service to continue.');return}partner={name:$('#partnerName').value.trim(),area:$('#partnerArea').value.trim(),rate:Number($('#partnerRate').value),availability:$('#partnerAvailability').value,bio:$('#partnerBio').value.trim(),skills,available:true,created:partner?.created||Date.now()};save('partner',partner);closeModal();renderPartner();renderJobs();toast('Welcome to PAHIMO Partners! Profile saved on this device.')}
}
function renderPartner(){const host=$('#partnerDashboard');if(!partner){host.innerHTML=`<div class="earn-banner"><div><span class="eyebrow">Your time. Your skills. Your call.</span><h2>Turn a little extra time into extra income.</h2><p>Choose one service you already know. Set your rate, share your hours, accept only the work that fits.</p><button class="btn btn-primary btn-small" id="startPartner">Create a free Partner profile →</button></div><div class="earn-total">₱ +</div></div><div class="stat-grid"><div class="stat"><small>Set your own</small><strong>Rates</strong><div class="up">Clear budget before you accept</div></div><div class="stat"><small>Choose your</small><strong>Hours</strong><div class="up">Take only work that fits</div></div><div class="stat"><small>Connect with</small><strong>People</strong><div class="up">Nearby or online</div></div></div><div class="panel-card"><h3 class="panel-title">Starting out? That’s welcome here.</h3><p class="small-muted">No fancy résumé needed. List a skill you’re comfortable with—an errand, a repair, a lesson, a design, or a remote task. Start with a small job and build from there.</p></div>`;$('#startPartner').onclick=partnerModal;return}const myJobs=accepted.filter(j=>j.partnerName===partner.name);const earnings=read('earnings',0)+myJobs.reduce((s,j)=>s+j.budget,0);host.innerHTML=`<div class="earn-banner"><div><span class="eyebrow">Partner dashboard</span><h2>Hi, ${esc(partner.name)}. Ready when you are.</h2><p>${partner.skills.slice(0,3).map(esc).join(' · ')} · ${esc(partner.area)}</p></div><div style="text-align:right"><div class="small-muted" style="color:#d8eadf">Demo earnings to date</div><div class="earn-total">₱${earnings.toLocaleString()}</div></div></div><div class="stat-grid"><div class="stat"><small>Demo earnings</small><strong>₱${earnings.toLocaleString()}</strong><div class="up">Illustrative only · no payout</div></div><div class="stat"><small>Jobs accepted</small><strong>${myJobs.length}</strong><div class="up">Your next step starts small</div></div><div class="stat"><small>Your starting rate</small><strong>₱${Number(partner.rate).toLocaleString()}</strong><div class="up">You control your price</div></div></div><div class="panel-card"><div class="job-top"><div class="provider-profile"><div class="profile-pic">🧑🏽‍🔧</div><div><h3 class="panel-title">${esc(partner.name)} <span class="badge neutral">New Partner</span></h3><div class="small-muted">📍 ${esc(partner.area)} · ${esc(partner.availability)} · Starting at ₱${Number(partner.rate).toLocaleString()}</div><div class="skills">${partner.skills.slice(0,8).map(s=>`<span class="skill-chip">${esc(s)}</span>`).join('')}</div></div></div><button class="btn btn-outline btn-small" id="editPartner">Edit profile</button></div><div class="settings-row"><div><strong>Available for work</strong><div class="small-muted">${partner.available?'People can see and invite you.':'You’re paused; your profile stays saved.'}</div></div><button class="switch ${partner.available?'on':''}" id="availabilitySwitch" aria-label="Toggle availability"></button></div></div>`;$('#editPartner').onclick=partnerModal;$('#availabilitySwitch').onclick=()=>{partner.available=!partner.available;save('partner',partner);renderPartner();toast(partner.available?'You’re available for new work.':'Availability paused.')}}
function submitPartnerOffer(requestId,amount,kind='counter'){
 if(!partner){toast('Create a Partner profile before sending an offer.');partnerModal();return}
 if(!partner.available){toast('Your Partner profile is paused. Turn availability on to offer.');return}
 const r=requests.find(x=>x.id===requestId);if(!r||r.provider){toast('This request is no longer open.');return}
 if(r.category!=='Other / Custom Request'&&!partner.skills.includes(r.subcategory)){toast('This request does not match a service on your Partner profile.');return}
 const value=Number(amount);if(!Number.isFinite(value)||value<50){toast('Enter an offer of at least ₱50.');return}
 r.offers=r.offers||[];const existing=r.offers.find(o=>o.partnerName===partner.name);if(existing){existing.amount=value;existing.kind=kind;existing.updated=Date.now()}else r.offers.push({id:'o'+Date.now(),partnerName:partner.name,amount:value,kind,created:Date.now()});r.status='Partner offer received';save('requests',requests);renderRequests();renderJobs();toast(kind==='match'?'Match sent. The customer can choose your offer.':'Counteroffer sent. The customer can review it.')
}
function acceptRequestOffer(requestId,offerId){
 const r=requests.find(x=>x.id===requestId),offer=r&&(r.offers||[]).find(o=>o.id===offerId);if(!r||!offer||r.provider){toast('That offer is no longer available.');return}
 r.provider=offer.partnerName;r.agreedPrice=Number(offer.amount);r.acceptedOfferId=offer.id;r.status='Booking confirmed';save('requests',requests);
 if(!chats.some(c=>c.requestId===r.id)){chats.unshift({id:'c'+Date.now(),name:offer.partnerName,requestId:r.id,messages:[{mine:false,text:`Your offer of ₱${Number(offer.amount).toLocaleString()} is accepted. Let’s confirm the details and timing here.`}]});save('chats',chats)}
 renderRequests();renderJobs();renderPartner();toast(`You chose ${offer.partnerName} at ₱${Number(offer.amount).toLocaleString()}. No payment is charged in this demo.`)
}
function renderJobs(){
 const list=$('#jobsList'),myids=accepted.map(j=>j.id),staticJobs=JOBS.filter(j=>jobTab==='mine'?myids.includes(j.id):jobTab==='nearby'?j.mode==='nearby':jobTab==='online'?j.mode==='online':true);
 const staticHtml=staticJobs.map(j=>{const mine=myids.includes(j.id);return `<article class="job-card"><div class="job-top"><div><div class="job-title">${j.emoji} ${esc(j.title)}</div><div class="job-desc">${esc(j.desc)}</div></div><span class="badge neutral">${j.mode==='online'?'Online':'Nearby'}</span></div><div class="job-meta"><span>📍 ${esc(j.place)}</span><span>🕒 ${esc(j.when)}</span><span>${esc(j.cat)} · ${esc(j.skill)}</span></div><div class="job-footer"><div><div class="job-price">₱${j.budget.toLocaleString()}</div><div class="small-muted">Customer offer</div></div>${mine?'<span class="badge">✓ Accepted</span>':`<button class="btn btn-green btn-small" data-accept="${j.id}">Match ₱${j.budget.toLocaleString()} →</button>`}</div></article>`}).join('');
 const requestHtml=requests.map(r=>{const online=String(r.mode).startsWith('Online'),own=(r.offers||[]).find(o=>partner&&o.partnerName===partner.name),isMine=partner&&r.provider===partner.name;
 if(jobTab==='mine'){if(!own&&!isMine)return ''}else{if(r.provider)return '';if(jobTab==='nearby'&&online||jobTab==='online'&&!online)return '';if(partner&&r.category!=='Other / Custom Request'&&!partner.skills.includes(r.subcategory))return ''}
 const label=r.subcategory||r.customService||r.category,matching=`<button class="btn btn-green btn-small" data-match-request="${esc(r.id)}">Match ₱${Number(r.budget).toLocaleString()}</button>`,counter=`<div class="counter-line"><input type="number" min="50" step="50" id="counter-${esc(r.id)}" aria-label="Your counteroffer for ${esc(label)}" placeholder="Your price ₱" value="${own&&own.kind==='counter'?Number(own.amount):''}"><button class="btn btn-outline btn-small" data-counter-request="${esc(r.id)}">${own?'Update':'Send'} counteroffer</button></div>`;
 const action=isMine?`<span class="badge">✓ Booking confirmed · ₱${Number(r.agreedPrice??r.budget).toLocaleString()}</span>`:own?`<div class="offer-note">Your ${own.kind==='match'?'matched offer':'counteroffer'}: ₱${Number(own.amount).toLocaleString()} · waiting for the customer to choose.</div>${matching}${counter}`:`<p class="small-muted">Match the customer’s price or suggest your own. No pressure to accept if it doesn’t work for you.</p><div class="offer-response">${matching}${counter}</div>`;
 const offerCount=(r.offers||[]).length;
 return `<article class="job-card"><div class="job-top"><div><div class="job-title">✨ ${esc(r.category)} · ${esc(label)}</div><div class="job-desc">${esc(r.details)}</div></div><span class="badge neutral">${online?'Online':'Nearby'}</span></div><div class="job-meta"><span>📍 ${esc(r.location)}</span><span>🗓 ${esc(r.date)} · ${esc(r.time)}</span><span>${offerCount?`${offerCount} Partner offer${offerCount===1?'':'s'}`:'Open request'}</span></div><div class="job-footer"><div><div class="job-price">₱${Number(r.budget).toLocaleString()}</div><div class="small-muted">Customer’s service offer</div></div>${action}</div></article>`
 }).join('');
 const allHtml=staticHtml+requestHtml;list.innerHTML=allHtml||'<div class="empty-state" style="grid-column:1/-1"><div class="big">✳</div><strong>No jobs fit this view yet</strong><p>New customer offers will appear here. You can choose to match the offer or send a counteroffer.</p></div>';
 $$('[data-accept]').forEach(b=>b.onclick=()=>acceptJob(b.dataset.accept));$$('[data-match-request]').forEach(b=>b.onclick=()=>{const r=requests.find(x=>x.id===b.dataset.matchRequest);if(r)submitPartnerOffer(r.id,r.budget,'match')});$$('[data-counter-request]').forEach(b=>b.onclick=()=>{const id=b.dataset.counterRequest,input=document.getElementById('counter-'+id);if(input)submitPartnerOffer(id,Number(input.value),'counter')})
}
function acceptJob(id){if(!partner){toast('Create your Partner profile first.');partnerModal();return}const j=JOBS.find(x=>x.id===id);if(!j)return;if(accepted.some(x=>x.id===id)){toast('You’ve already accepted this one.');return}const item={...j,partnerName:partner.name,acceptedAt:Date.now()};accepted.unshift(item);save('accepted',accepted);chats.unshift({id:'c'+Date.now(),name:'Customer · '+j.title,jobId:j.id,messages:[{mine:false,text:'Thanks for accepting! Let’s confirm the details and timing here.'}]});save('chats',chats);renderPartner();renderJobs();toast('Job accepted — say hello in your Inbox!')}
function renderChat(){const list=$('#threadList');if(!chats.length){list.innerHTML='<div class="empty-state" style="border:0;padding:22px 10px"><div class="big">✉</div><strong>No messages yet</strong></div>';$('#chatName').textContent='Your PAHIMO inbox';$('#chatSubtitle').textContent='A match will appear here after a request.';$('#messages').innerHTML='<div class="empty-state" style="border:0;background:transparent;padding:38px 10px"><div class="big">💬</div><strong>Your conversations live here</strong><p>Request a service or accept a job to start a chat.</p></div>';return}list.innerHTML=chats.map(c=>`<div class="chat-thread ${c.id===read('activeChat',chats[0].id)?'selected':''}" data-thread="${c.id}"><div class="thread-avatar">👋</div><div class="thread-copy"><strong>${esc(c.name)}</strong><small>${esc(c.messages.at(-1)?.text||'Start a conversation')}</small></div></div>`).join('');$$('[data-thread]').forEach(x=>x.onclick=()=>{save('activeChat',x.dataset.thread);renderChat()});const active=chats.find(c=>c.id===read('activeChat',chats[0].id))||chats[0];$('#chatName').textContent=active.name;$('#chatSubtitle').textContent='PAHIMO demo chat · confirm scope and budget before work.';$('#messages').innerHTML=active.messages.map(m=>`<div class="bubble ${m.mine?'mine':''}">${esc(m.text)}</div>`).join('');$('#messages').scrollTop=$('#messages').scrollHeight}
function renderAdminServices(query=''){
 const q=query.toLowerCase().trim(),items=CATEGORIES.filter(c=>!q||c.name.toLowerCase().includes(q)||c.items.some(x=>x.toLowerCase().includes(q)));
 $('#adminServices').innerHTML=items.length?items.map(c=>`<details class="admin-service"><summary><span>${c.icon} ${esc(c.name)}</span><small>Visible in demo · ${c.items.length} services</small></summary><div class="admin-tags">${c.items.map(x=>`<span class="skill-chip">${esc(x)}</span>`).join('')}</div></details>`).join(''):'<div class="empty-state">No matching service. Try another word.</div>'
}
function formatDemoDate(v){return v?new Date(v).toLocaleString():'—'}
function renderAdminPaymentRow(x){
 const c=x.refundCase,open=c&&['Pending','Approved'].includes(c.status),resolved=c&&['Denied','Refunded'].includes(c.status),money=n=>'₱'+Number(n||0).toLocaleString();
 let refund='';
 if(c){refund=`<div class="refund-admin-tools"><div class="refund-status-line"><strong>Refund: ${esc(c.status)}</strong><span class="badge neutral">Original method: ${esc(c.originalPaymentMethod||x.methodName)}</span></div><div class="ledger-meta">Requested ${formatDemoDate(c.requestedAt)} · Requested amount ${money(c.requestedAmount)} · Reason: ${esc(c.reason)} · Evidence note: ${esc(c.evidenceNote||'Not provided')} · Decision note: ${esc(c.decisionNote||'No decision note yet')}${c.additionalInfo?` · Customer follow-up: ${esc(c.additionalInfo)}`:''}</div>${c.status==='Pending'?`<div class="field"><label for="refund-note-${esc(x.id)}">Admin decision note / denial reason / info request</label><input id="refund-note-${esc(x.id)}" placeholder="Required for denial or more-info request"></div><div class="field"><label for="refund-partial-${esc(x.id)}">Partial refund amount · ₱</label><input id="refund-partial-${esc(x.id)}" type="number" min="1" max="${Number(c.requestedAmount)}" step="1" placeholder="Enter amount for partial approval"></div><div class="ledger-actions"><button class="btn btn-green btn-small" data-refund-full="${esc(x.id)}">Approve requested amount</button><button class="btn btn-outline btn-small" data-refund-partial="${esc(x.id)}">Approve partial</button><button class="btn btn-outline btn-small" data-refund-deny="${esc(x.id)}">Deny with reason</button><button class="btn btn-outline btn-small" data-refund-info="${esc(x.id)}">Request more info</button></div>`:''}${c.status==='Approved'?`<p class="refund-admin-note">Approved amount: ${money(c.approvedAmount)} · Prefer refund to ${esc(c.originalPaymentMethod||x.methodName)} where possible. Record “Refunded” only after provider refund confirmation or documented manual reconciliation.</p><button class="btn btn-outline btn-small" data-refund-mark-refunded="${esc(x.id)}">Record refunded · demo</button>`:''}</div>`}
 const hold=open?'Refund case open—Partner payable remains Pending.':x.payoutStatus==='pending'?'Pending until settlement/refund window is closed.':'';
 let payoutAction='';
 if(x.payoutStatus==='pending'&&!open&&!c){payoutAction=`<button class="btn btn-outline btn-small" data-ledger-available="${esc(x.id)}">Confirm refund window closed → Available · demo</button>`}
 else if(x.payoutStatus==='pending'&&resolved&&c.status==='Denied'){payoutAction=`<button class="btn btn-outline btn-small" data-ledger-available="${esc(x.id)}">Reconcile resolved case → Available · demo</button>`}
 else if(x.payoutStatus==='pending'&&resolved&&c.status==='Refunded'){payoutAction=`<div class="field"><label for="payable-adjust-${esc(x.id)}">Remaining Partner payable after refund reconciliation · ₱</label><input id="payable-adjust-${esc(x.id)}" type="number" min="0" max="${Number(x.originalPartnerPayable??x.partnerPayable)}" step="1" placeholder="Enter reconciled amount"></div><button class="btn btn-outline btn-small" data-ledger-available-refunded="${esc(x.id)}">Reconcile & mark Available · demo</button>`}
 else if(open)payoutAction='<span class="badge neutral">Partner payable on hold until case resolved</span>';
 else if(x.payoutStatus==='requested')payoutAction=`<button class="btn btn-green btn-small" data-ledger-paid="${esc(x.id)}">Approve & record paid · demo</button><button class="btn btn-outline btn-small" data-ledger-return="${esc(x.id)}">Return to Available</button>`;
 const refundStatus=c?c.status:'No request';
 return `<div class="ledger-row"><div class="ledger-row-head"><strong>${esc(x.id)} · ${esc(x.methodName)} · ${money(x.customerAmount)}</strong><span class="badge neutral">Payable: ${esc(x.payoutStatus)}</span></div><div class="ledger-meta">Payment: ${esc(x.paymentStatus)} · Partner: ${esc(x.partnerName)} · PAHIMO fee: ${money(x.platformFee)} · Partner payable: ${money(x.partnerPayable)} · Refund status: ${esc(refundStatus)}${x.payoutStatus==='paid'&&c&&open?' · Partner already paid—recovery needs a written rule':''}${hold?' · '+hold:''}</div>${refund}<div class="ledger-actions">${payoutAction}${x.payoutStatus==='available'||x.payoutStatus==='requested'||x.payoutStatus==='paid'?`<button class="btn btn-outline btn-small" data-ledger-refund-review="${esc(x.id)}">Open refund/reconciliation view</button>`:''}</div></div>`
}
function renderAdminPaymentLedger(){
 const sum=status=>demoLedger.filter(x=>x.payoutStatus===status).reduce((a,x)=>a+Number(x.partnerPayable||0),0),money=n=>'₱'+Number(n||0).toLocaleString(),refundCases=demoLedger.map(x=>x.refundCase).filter(Boolean),openCases=refundCases.filter(x=>['Pending','Approved'].includes(x.status)).length,refunded=refundCases.filter(x=>x.status==='Refunded').reduce((a,x)=>a+Number(x.refundedAmount||0),0);
 $('#adminPayStats').innerHTML=`<div class="stat"><small>Pending payable</small><strong>${money(sum('pending'))}</strong><div class="up">Settlement/window or case hold</div></div><div class="stat"><small>Available</small><strong>${money(sum('available'))}</strong><div class="up">Ready to request</div></div><div class="stat"><small>Requested</small><strong>${money(sum('requested'))}</strong><div class="up">Needs Admin review</div></div><div class="stat"><small>Paid · demo records</small><strong>${money(sum('paid'))}</strong><div class="up">Manually recorded</div></div><div class="stat"><small>Open refund cases</small><strong>${openCases}</strong><div class="up">Pending or approved</div></div><div class="stat"><small>Refunded · demo</small><strong>${money(refunded)}</strong><div class="up">Original method preferred</div></div>`;
 $('#adminPaymentLedger').innerHTML=demoLedger.length?demoLedger.map(renderAdminPaymentRow).join(''):'<div class="empty-state" style="padding:18px">No payment or payout records. Simulated checkouts appear here only in this browser.</div>';
 $$('[data-ledger-available]').forEach(b=>b.onclick=()=>updateDemoLedger(b.dataset.ledgerAvailable,x=>{x.payoutStatus='available';x.refundWindowClosed=true;x.availableAt=Date.now()}));
 $$('[data-ledger-available-refunded]').forEach(b=>b.onclick=()=>{const x=demoLedger.find(v=>v.id===b.dataset.ledgerAvailableRefunded),input=document.getElementById('payable-adjust-'+b.dataset.ledgerAvailableRefunded),n=Number(input?.value),max=Number(x?.originalPartnerPayable??x?.partnerPayable);if(!x||!Number.isFinite(n)||n<0||n>max){toast('Enter a valid remaining payable after refund reconciliation.');return}updateDemoLedger(x.id,v=>{v.partnerPayable=n;v.payoutStatus='available';v.refundWindowClosed=true;v.availableAt=Date.now()})});
 $$('[data-ledger-paid]').forEach(b=>b.onclick=()=>updateDemoLedger(b.dataset.ledgerPaid,x=>{x.payoutStatus='paid';x.paidAt=Date.now()}));
 $$('[data-ledger-return]').forEach(b=>b.onclick=()=>updateDemoLedger(b.dataset.ledgerReturn,x=>{x.payoutStatus='available'}));
 $$('[data-ledger-refund-review]').forEach(b=>b.onclick=()=>{const x=demoLedger.find(v=>v.id===b.dataset.ledgerRefundReview);if(x?.refundCase)document.getElementById('refund-case-'+x.id)?.scrollIntoView({behavior:'smooth',block:'center'});else toast('No refund request is recorded for this demo payment.')});
 $$('[data-refund-full]').forEach(b=>b.onclick=handleDemoRefundDecision(b.dataset.refundFull,'approve-full'));
 $$('[data-refund-partial]').forEach(b=>b.onclick=handleDemoRefundDecision(b.dataset.refundPartial,'approve-partial'));
 $$('[data-refund-deny]').forEach(b=>b.onclick=handleDemoRefundDecision(b.dataset.refundDeny,'deny'));
 $$('[data-refund-info]').forEach(b=>b.onclick=handleDemoRefundDecision(b.dataset.refundInfo,'more-info'));
 $$('[data-refund-mark-refunded]').forEach(b=>b.onclick=()=>updateDemoRefund(b.dataset.refundMarkRefunded,c=>{c.status='Refunded';c.refundedAmount=Number(c.approvedAmount||0);c.refundedAt=Date.now();c.decisionNote=(c.decisionNote?c.decisionNote+' · ':'')+'Refund recorded in demo; original method preferred.'}));
}
function handleDemoRefundDecision(id,action){return b=>{const x=demoLedger.find(v=>v.id===id);if(!x?.refundCase)return;const c=x.refundCase,note=document.getElementById('refund-note-'+id)?.value.trim()||'';if(action==='approve-full')updateDemoRefund(id,c=>{c.status='Approved';c.approvedAmount=Number(c.requestedAmount);c.decisionNote=note||'Approved full requested amount · demo';c.decidedAt=Date.now()});else if(action==='approve-partial'){const amount=Number(document.getElementById('refund-partial-'+id)?.value);if(!Number.isFinite(amount)||amount<=0||amount>Number(c.requestedAmount)){toast('Enter a partial refund between ₱1 and the requested amount.');return}updateDemoRefund(id,c=>{c.status='Approved';c.approvedAmount=amount;c.decisionNote=note||'Approved partial amount · demo';c.decidedAt=Date.now()})}else if(action==='deny'){if(!note){toast('Add a reason before denying this request.');return}updateDemoRefund(id,c=>{c.status='Denied';c.decisionNote=note;c.decidedAt=Date.now()})}else if(action==='more-info'){if(!note){toast('Say what information is needed.');return}updateDemoRefund(id,c=>{c.status='Pending';c.decisionNote='More information requested: '+note;c.infoRequestedAt=Date.now()})}}
}
function updateDemoRefund(id,fn){const x=demoLedger.find(v=>v.id===id);if(!x?.refundCase)return;fn(x.refundCase);if(x.payoutStatus!=='paid')x.payoutStatus='pending';save('demoLedger',demoLedger);renderAdminPaymentLedger();renderPayments();toast('Refund case updated in this browser only; no refund was sent.')}
function updateDemoLedger(id,fn){const item=demoLedger.find(x=>x.id===id);if(!item)return;fn(item);save('demoLedger',demoLedger);renderAdminPaymentLedger();renderPayments();toast('Demo ledger updated locally only; no money moved.')}

