 $('#adminRequestView').innerHTML=requests.length?requests.slice(0,15).map(r=>`<div class="admin-row"><div class="admin-row-head"><strong>${esc(r.category)}${r.subcategory?' · '+esc(r.subcategory):''}</strong><span class="badge neutral">${esc(r.status)}</span></div><div class="small-muted">Customer offer ₱${Number(r.budget||0).toLocaleString()} · ${(r.offers||[]).length} Partner offer(s) · ${esc(r.location||'')}</div></div>`).join(''):'<p class="small-muted">No requests saved in this browser yet.</p>';
 $('#adminServiceSearch').oninput=e=>renderAdminServices(e.target.value);$('#adminBack').onclick=()=>navigate('account');renderAdminPaymentLedger();$('#adminPayments').onclick=()=>navigate('payments')
