 $('#customerPaymentStatus').textContent=selected?`Demo selection: ${PAYMENT_METHODS.find(m=>m[0]===selected)?.[1]}. No payment started.`:'Choose an example checkout method. No money moves in this preview.';
 $$('[data-customer-method]').forEach(b=>b.onclick=()=>{save('customerPaymentMethod',b.dataset.customerMethod);renderPayments()});
 const payoutChoices=[['bank','Supported bank account'],['gcash','GCash'],['maya','Maya'],['other','Other supported e-wallet']],payout=read('partnerPayoutMethod','');
